import sys

def solve():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n = int(input_data[0])
    lines = input_data[1:n+1]

    balance = 0
    for line in lines:
        for char in line:
            if char == '{':
                balance += 1
            elif char == '}':
                balance -= 1
                if balance < 0:
                    print("N")
                    return

    if balance == 0:
        print("S")
    else:
        print("N")

if __name__ == '__main__':
    solve()
